files.content:
/* A deep-tinted shape with a slow light sweep, rather than a grey pulse:
   on the tinted page a neutral grey reads as dirt. */
.skeleton {
  display: block;
  flex-shrink: 0;
  background:
    linear-gradient(
      100deg,
      transparent 20%,
      rgba(var(--rgb-white), 0.55) 45%,
      rgba(var(--rgb-white), 0.55) 55%,
      transparent 80%
    ),
    rgba(var(--rgb-brand-deep), 0.075);
  background-size: 220% 100%, 100% 100%;
  background-repeat: no-repeat;
  background-position: 120% 0, 0 0;
  animation: sweep 1.6s var(--ease) infinite;
}

.block {
  border-radius: var(--r-xs);
}

.text {
  border-radius: var(--r-2xs);
}

.circle {
  border-radius: var(--r-circle, 50%);
}

/* A caller-set radius (the radius prop) arrives as --skeleton-radius, not an
   inline border-radius, so a brand layer that sets --r-flat (the public
   layer: 0) can still square it. Declared after the variants so it wins. */
.custom {
  border-radius: var(--r-flat, var(--skeleton-radius));
}

.lines {
  display: flex;
  flex-direction: column;
  gap: 9px;
  width: 100%;
}

@keyframes sweep {
  to {
    background-position: -120% 0, 0 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .skeleton {
    animation: none;
  }
}

import type { CSSProperties } from "react";
import { cx } from "../_internal/cx";
import styles from "./Skeleton.module.css";

export type SkeletonProps = {
  /** Size to the real content it stands in for, not a generic block. */
  width?: number | string;
  height?: number | string;
  /** text = a line of text at the given font size's height; circle = avatar. */
  variant?: "text" | "block" | "circle";
  radius?: number | string;
  className?: string;
  style?: CSSProperties;
};

/** A placeholder shape. Decorative: wrap loading regions in aria-busy and give them a label. */
export function Skeleton({ width = "100%", height, variant = "block", radius, className, style }: SkeletonProps) {
  const h = height ?? (variant === "text" ? "0.9em" : variant === "circle" ? width : 16);
  return (
    <span data-slot="skeleton"
      aria-hidden="true"
      className={cx(styles.skeleton, styles[variant], radius !== undefined && styles.custom, className)}
      style={{
        width,
        height: h,
        ...(radius !== undefined
          ? ({ "--skeleton-radius": typeof radius === "number" ? `${radius}px` : radius } as CSSProperties)
          : null),
        ...style,
      }}
    />
  );
}

export type SkeletonTextProps = {
  lines?: number;
  /** Last line is shorter, as real paragraphs are. */
  lastLineWidth?: string;
  lineHeight?: number;
  className?: string;
};

export function SkeletonText({ lines = 3, lastLineWidth = "62%", lineHeight = 14, className }: SkeletonTextProps) {
  return (
    <span data-slot="skeleton-text" className={cx(styles.lines, className)} aria-hidden="true">
      {Array.from({ length: lines }, (_, i) => (
        <Skeleton key={i} variant="text" height={lineHeight * 0.72} width={i === lines - 1 && lines > 1 ? lastLineWidth : "100%"} />
      ))}
    </span>
  );
}
